GUARD_BODY.early-return:
if ((object->flags & 1) == 0)
        return;

    if (win_DrawBitMap(object->bitmapOffset, object->bitmapArgument, value) == 0) {
        color = (int)monoPat | _foreColor;
        GRectFill(object, color);
    }

GUARD_BODY.positive-guard:
if ((object->flags & 1) != 0) {
        if (win_DrawBitMap(object->bitmapOffset, object->bitmapArgument, value) == 0) {
            color = (int)monoPat | _foreColor;
            GRectFill(object, color);
        }
    }
